import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void batch_norm_kernel(
    const half* input,
    half* output,
    const half* weight,
    const half* bias,
    const half* mean,
    const half* var,
    const float eps,
    const int batch_size,
    const int channels,
    const int height,
    const int width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * height * width;

    if (idx >= total_elements) return;

    // Calculate which batch, channel, and spatial position this thread handles
    int w = idx % width;
    int h = (idx / width) % height;
    int c = (idx / (width * height)) % channels;
    int b = idx / (width * height * channels);

    // Get the corresponding channel statistics
    half chan_mean = mean[c];
    half chan_var = var[c];
    half chan_weight = weight[c];
    half chan_bias = bias[c];

    // Normalize and scale
    half normalized = __hdiv(__hsub(input[idx], chan_mean), __hadd(__hsqrt(chan_var), __float2half(eps)));
    output[idx] = __hadd(__hmul(chan_weight, normalized), chan_bias);
}

// Host function to launch the kernel
extern "C" void launch_batch_norm(
    const half* input,
    half* output,
    const half* weight,
    const half* bias,
    const half* mean,
    const half* var,
    const float eps,
    const int batch_size,
    const int channels,
    const int height,
    const int width
) {
    int total_elements = batch_size * channels * height * width;
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    batch_norm_kernel<<<grid_size, block_size>>>(
        input, output, weight, bias, mean, var, eps, 
        batch_size, channels, height, width
    );

    cudaDeviceSynchronize();
}
"""

# Python wrapper class
class ModelNew(torch.nn.Module):
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.num_features = num_features
        self.weight = torch.nn.Parameter(torch.ones(num_features, dtype=torch.float16))
        self.bias = torch.nn.Parameter(torch.zeros(num_features, dtype=torch.float16))
        self.register_buffer('running_mean', torch.zeros(num_features, dtype=torch.float16))
        self.register_buffer('running_var', torch.ones(num_features, dtype=torch.float16))
        self.eps = 1e-5

        # Compile CUDA extension
        self.cubin = load_inline(
            name="batch_norm_cuda",
            cpp_sources=[],
            cuda_sources=[cuda_source],
            functions=["launch_batch_norm"],
            verbose=False
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, channels, height, width = x.shape

        # Ensure we're using the right device and dtype
        x = x.to(dtype=torch.float16, device=x.device)

        # Create output tensor
        output = torch.empty_like(x)

        # Launch CUDA kernel
        self.cubin.launch_batch_norm(
            x.data_ptr(),
            output.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            self.running_mean.data_ptr(),
            self.running_var.data_ptr(),
            self.eps,
            batch_size,
            channels,
            height,
            width
        )

        return output

